def wrap_spiral(R,C,H=11,W=11,narms=10,vwrap=True,hwrap=False):
    g=np.zeros((H,W),int); g[R,C]=1
    r,c=R,C
    dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    d=0; arm=2
    for i in range(narms):
        dr,dc=dirs[d%4]
        for _ in range(arm):
            r+=dr; c+=dc
            if vwrap and not (0<=r<H): r%=H
            if hwrap and not (0<=c<W): c%=W
            if 0<=r<H and 0<=c<W: g[r,c]=1
        d+=1
        if i%2==1: arm+=2
    return g
